mapper.select:
/* AppChkLst01Mapper.selectSiteNm */
SELECT
    SITE_NM
FROM TB_SITE
WHERE 1=1
  AND CMPNY_CD = #{ cmpnyCd }
  AND SITE_CD  = #{ siteCd }

mapper.insert:
/* AppChkLst01Mapper.mergeChkptInspectAnswer */
INSERT INTO TB_CHKPT_INSPECT_ANSWER (
    CMPNY_CD
    , SITE_CD
    , CHKPT_CD
    , INSPECT_ITEM_CD
    , WORK_DATE
    , INSPECT_ANSWER_TYPE
    , ANSWER_DESC
    , FILE_MGMT_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES(
    #{token.gv_cmpnyCd}
    , #{param.siteCd}
    , #{param.chkptCd}
    , #{param.inspectItemCd}
    , #{param.workDate}
    , #{param.inspectAnswerType}
    , #{param.answerDesc}
    , #{param.fileMgmtCd}
    , #{token.gv_userCd}
    , NOW()
    , #{token.gv_userCd}
    , NOW()
)
ON DUPLICATE KEY UPDATE
    INSPECT_ANSWER_TYPE = VALUES(INSPECT_ANSWER_TYPE)
    , ANSWER_DESC       = VALUES(ANSWER_DESC)
    , FILE_MGMT_CD      = VALUES(FILE_MGMT_CD)
    , UPDATE_NO         = #{token.gv_userCd}
    , UPDATE_DATE       = NOW()
